// Browser-native bitmap re-encoding; only bounded metadata-free JPEGs are persisted.
export const IMAGE_POLICY=Object.freeze({inputBytes:4*1024*1024,inputSide:4096,inputPixels:8000000,outputSide:768,outputBytes:192*1024});
const check=(ok,message)=>{if(!ok)throw Error(message);};
const signature=[137,80,78,71,13,10,26,10],prefix='data:image/jpeg;base64,';
const base64=bytes=>{let text='';for(let i=0;i<bytes.length;i+=8192)text+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(text);};
export function inspectNormalizedImage(value){
 check(typeof value==='string'&&value.startsWith(prefix)&&value.length<=prefix.length+Math.ceil(IMAGE_POLICY.outputBytes/3)*4,'Unsupported normalized image.');
 const encoded=value.slice(prefix.length);check(encoded.length>0&&/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(encoded),'Malformed image encoding.');
 const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)),view=new DataView(bytes.buffer);check(bytes.length<=IMAGE_POLICY.outputBytes&&base64(bytes)===encoded&&bytes[0]===255&&bytes[1]===216,'Malformed JPEG.');
 let pos=2,width,height,scans=0,quantization=false,huffman=false,ended=false;while(pos<bytes.length){check(bytes[pos++]===255,'Malformed JPEG marker.');while(bytes[pos]===255)pos++;const marker=bytes[pos++];if(marker===217){ended=true;break;}check([219,196,192,194,221,218].includes(marker)&&pos+2<=bytes.length,'Unsupported image metadata or marker.');const length=view.getUint16(pos);check(length>=2&&pos+length<=bytes.length,'Truncated JPEG segment.');
  if(marker===219)quantization=true;if(marker===196)huffman=true;
  if(marker===192||marker===194){check(!width&&length===17&&bytes[pos+2]===8&&bytes[pos+7]===3,'Invalid JPEG frame.');height=view.getUint16(pos+3);width=view.getUint16(pos+5);}
  pos+=length;if(marker===218){scans++;check(width&&quantization&&huffman,'Missing JPEG tables.');while(pos<bytes.length){if(bytes[pos]!==255){pos++;continue;}const next=bytes[pos+1];if(next===0||next>=208&&next<=215){pos+=2;continue;}break;}}
 }
 check(ended&&pos===bytes.length&&scans>0&&width>0&&height>0&&width<=IMAGE_POLICY.outputSide&&height<=IMAGE_POLICY.outputSide,'Invalid JPEG pixels, dimensions or end.');return {width,height,bytes:bytes.length};
}
export const validNormalizedImage=value=>{try{inspectNormalizedImage(value);return true;}catch{return false;}};
export function inputDimensions(bytes,type){
 const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let width,height;
 if(type==='image/png'){check(bytes.length>=24&&signature.every((v,i)=>bytes[i]===v)&&view.getUint32(8)===13&&String.fromCharCode(...bytes.subarray(12,16))==='IHDR','This is not a PNG bitmap.');width=view.getUint32(16);height=view.getUint32(20);}
 else if(type==='image/jpeg'){check(bytes.length>4&&bytes[0]===255&&bytes[1]===216,'This is not a JPEG bitmap.');let pos=2;while(pos+4<=bytes.length){check(bytes[pos++]===255,'Malformed JPEG.');while(bytes[pos]===255)pos++;const marker=bytes[pos++];if(marker===217||marker===218)break;if(marker===1||marker>=208&&marker<=215)continue;check(pos+2<=bytes.length,'Truncated JPEG.');const length=view.getUint16(pos);check(length>=2&&pos+length<=bytes.length,'Truncated JPEG segment.');if([192,193,194,195,197,198,199,201,202,203,205,206,207].includes(marker)){check(length>=8,'Malformed JPEG dimensions.');height=view.getUint16(pos+3);width=view.getUint16(pos+5);break;}pos+=length;}}
 else if(type==='image/webp'){check(bytes.length>=30&&String.fromCharCode(...bytes.subarray(0,4))==='RIFF'&&String.fromCharCode(...bytes.subarray(8,12))==='WEBP'&&view.getUint32(4,true)+8===bytes.length,'This is not a WebP bitmap.');const kind=String.fromCharCode(...bytes.subarray(12,16));if(kind==='VP8X'){width=1+bytes[24]+(bytes[25]<<8)+(bytes[26]<<16);height=1+bytes[27]+(bytes[28]<<8)+(bytes[29]<<16);}else if(kind==='VP8L'){check(bytes[20]===47,'Malformed WebP.');const n=view.getUint32(21,true);width=(n&16383)+1;height=((n>>>14)&16383)+1;}else if(kind==='VP8 '){check(bytes[23]===157&&bytes[24]===1&&bytes[25]===42,'Malformed WebP.');width=view.getUint16(26,true)&16383;height=view.getUint16(28,true)&16383;}}
 check(Number.isInteger(width)&&Number.isInteger(height)&&width>0&&height>0&&width<=IMAGE_POLICY.inputSide&&height<=IMAGE_POLICY.inputSide&&width*height<=IMAGE_POLICY.inputPixels,'Image exceeds 4096px per side or 8 megapixels, or is malformed.');return {width,height};
}
export function stripJPEGMetadata(bytes){const parts=[bytes.subarray(0,2)],view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let pos=2;while(pos<bytes.length){const start=pos;check(bytes[pos++]===255,'Malformed native JPEG.');const marker=bytes[pos++];if(marker===218||marker===217){parts.push(bytes.subarray(start));break;}check(pos+2<=bytes.length,'Truncated native JPEG.');const size=view.getUint16(pos);check(size>=2&&pos+size<=bytes.length,'Truncated native JPEG segment.');pos+=size;if(!(marker>=224&&marker<=239)&&marker!==254)parts.push(bytes.subarray(start,pos));}const result=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let offset=0;for(const part of parts){result.set(part,offset);offset+=part.length;}return result;}
export async function decodeNormalizedImage(value){const expected=inspectNormalizedImage(value),blob=new Blob([Uint8Array.from(atob(value.slice(prefix.length)),c=>c.charCodeAt(0))],{type:'image/jpeg'});let bitmap;try{bitmap=await createImageBitmap(blob);check(bitmap.width===expected.width&&bitmap.height===expected.height,'Decoded image dimensions disagree.');}finally{bitmap?.close();}}
export async function verifyStoredImages(state){const images=new Set();for(const m of Object.values(state.meals)){for(const value of [m.image,m.draft?.image,...m.versions.map(v=>v.image)])if(value?.startsWith('data:'))images.add(value);}for(const key of ['orders','coupons','ops'])for(const record of state[key]){const value=record.image??record.terms?.image;if(value?.startsWith('data:'))images.add(value);}for(const image of images)await decodeNormalizedImage(image);}
export async function normalizeUpload(file){
 check(file&&['image/png','image/jpeg','image/webp'].includes(file.type),'Choose a decoded PNG, JPEG or WebP bitmap. SVG and HTML are not supported.');check(file.size>0&&file.size<=IMAGE_POLICY.inputBytes,'Image must be at most 4 MiB.');const bytes=new Uint8Array(await file.arrayBuffer());inputDimensions(bytes,file.type);
 let bitmap;try{bitmap=await createImageBitmap(file,{imageOrientation:'none'});check(bitmap.width>0&&bitmap.height>0&&bitmap.width<=IMAGE_POLICY.inputSide&&bitmap.height<=IMAGE_POLICY.inputSide&&bitmap.width*bitmap.height<=IMAGE_POLICY.inputPixels,'Decoded image exceeds the pixel limit.');let scale=Math.min(1,IMAGE_POLICY.outputSide/bitmap.width,IMAGE_POLICY.outputSide/bitmap.height);for(let attempt=0;attempt<8;attempt++){const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.82));check(blob&&blob.type==='image/jpeg','JPEG re-encoding is unavailable.');if(blob.size<=IMAGE_POLICY.outputBytes){const normalized=prefix+base64(stripJPEGMetadata(new Uint8Array(await blob.arrayBuffer())));await decodeNormalizedImage(normalized);return normalized;}scale*=0.75;}throw Error('Normalized image remains too large.');}catch(err){throw Error(err.message?.startsWith('Decoded')?err.message:'This bitmap could not be decoded or normalized safely.');}finally{bitmap?.close();}
}
